<?php declare(strict_types=1); require_once __DIR__.'/../config/config.php'; require_once __DIR__.'/../config/database.php'; $db=db(); $token=preg_replace('/[^a-f0-9]/','',strtolower((string)($_GET['token']??''))); $s=$db->prepare('SELECT i.*,l.name client_name,l.company,l.email FROM invoices i JOIN leads l ON l.id=i.lead_id WHERE i.public_token=? LIMIT 1');$s->execute([$token]);$i=$s->fetch();if(!$i){http_response_code(404);exit('Invoice not found.');}$s=$db->prepare('SELECT * FROM invoice_items WHERE invoice_id=? ORDER BY sort_order,id');$s->execute([$i['id']]);$items=$s->fetchAll();$esc=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');function money3($v,$c){return $c.' '.number_format((float)$v,2);} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$esc($i['invoice_number'])?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5" style="max-width:950px"><div class="card border-0 shadow-sm"><div class="card-body p-4 p-md-5"><div class="d-flex justify-content-between border-bottom pb-4"><div><h1>Distinguished Web Services</h1><div class="text-muted">Invoice</div></div><div class="text-end"><strong><?=$esc($i['invoice_number'])?></strong><br>Issued: <?=$esc($i['issue_date'])?><br>Due: <?=$esc($i['due_date']?:'—')?></div></div><div class="my-4"><h2><?=$esc($i['title'])?></h2><div>Bill to: <strong><?=$esc($i['client_name'])?></strong><?php if($i['company']):?> — <?=$esc($i['company'])?><?php endif;?></div><div class="text-muted"><?=$esc($i['email'])?></div></div><div class="table-responsive"><table class="table"><thead><tr><th>Description</th><th class="text-end">Qty</th><th class="text-end">Unit</th><th class="text-end">Amount</th></tr></thead><tbody><?php foreach($items as $x):?><tr><td><?=$esc($x['description'])?></td><td class="text-end"><?=$esc($x['quantity'])?></td><td class="text-end"><?=money3($x['unit_price'],$i['currency'])?></td><td class="text-end"><?=money3($x['amount'],$i['currency'])?></td></tr><?php endforeach;?></tbody><tfoot><tr><td colspan="3" class="text-end">Subtotal</td><td class="text-end"><?=money3($i['subtotal'],$i['currency'])?></td></tr><tr><td colspan="3" class="text-end">Discount</td><td class="text-end">- <?=money3($i['discount'],$i['currency'])?></td></tr><tr><td colspan="3" class="text-end">Tax</td><td class="text-end"><?=money3($i['tax'],$i['currency'])?></td></tr><tr><td colspan="3" class="text-end fw-bold">Total</td><td class="text-end fw-bold"><?=money3($i['total'],$i['currency'])?></td></tr><tr><td colspan="3" class="text-end">Amount Paid</td><td class="text-end"><?=money3($i['amount_paid'],$i['currency'])?></td></tr><tr><td colspan="3" class="text-end fw-bold">Balance Due</td><td class="text-end fw-bold"><?=money3($i['balance_due'],$i['currency'])?></td></tr></tfoot></table></div><?php if(isset($_GET['payment'])):?><div class="alert alert-<?=($_GET['payment']==='successful'?'success':'warning')?>">Payment status: <strong><?=$esc($_GET['payment'])?></strong>. We are updating your invoice.</div><?php endif;?><?php if($i['balance_due']>0 && $i['status']!=='cancelled'):?><div class="alert alert-primary d-flex justify-content-between align-items-center"><span>Balance due: <strong><?=money3($i['balance_due'],$i['currency'])?></strong></span><a class="btn btn-primary" href="pay-invoice.php?token=<?=$esc($token)?>">Pay Now</a></div><?php elseif($i['status']==='paid'):?><div class="alert alert-success">This invoice has been paid in full.</div><?php endif;?><?php if($i['notes']):?><div class="mt-4"><strong>Notes</strong><p><?=nl2br($esc($i['notes']))?></p></div><?php endif;?><?php if($i['terms']):?><div class="mt-4"><strong>Terms & Conditions</strong><p><?=nl2br($esc($i['terms']))?></p></div><?php endif;?></div></div></main></body></html>